                owner: stratum,
                major: false,
            })
            placed += 1
        }
    }
    return placed
}

/** Seed or monthly top-up: operational homes toward target (120% of required). */
function ensureStratumHomesAtTarget(stratum, districtPops) {
    var totalPop = 0
    for (var dk in districtPops) {
